use vstd::prelude::*;

verus! {

/// Specification: what the output sequence must look like.
spec fn inserted_seq(s: Seq<i8>, delimiter: i8) -> Seq<i8> {
    if s.len() <= 1 {
        s
    } else {
        // length = 2*n - 1, with:
        //   out[2*k]   = s[k]
        //   out[2*k+1] = delimiter
        Seq::new(2 * s.len() - 1, |i: int|
            if i % 2 == 0 {
                s[i / 2]
            } else {
                delimiter
            }
        )
    }
}

fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> (result: Vec<i8>)
    ensures
        result@ == inserted_seq(numbers@, delimiter),
{
    let n: usize = numbers.len();
    if n <= 1 {
        // Returning the input unchanged satisfies the spec for len <= 1.
        return numbers;
    }

    let mut out: Vec<i8> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == numbers.len(),
            0 <= i <= n,
            // Out is exactly the delimiter-inserted version of the prefix numbers[0..i)
            out@ == inserted_seq(numbers@.subrange(0, i as int), delimiter),
        decreases n - i,
    {
        // push the next number
        out.push(numbers[i]);

        // If there is another number after this, insert delimiter between them.
        if i + 1 < n {
            out.push(delimiter);
        }

        i = i + 1;
    }

    // Now i == n, so out is the inserted_seq of the full input.
    proof {
        assert(numbers@.subrange(0, n as int) == numbers@);
    }
    out
}

} // verus!

